function OptanonWrapper() {
  if (!OneTrust.IsAlertBoxClosed()) {
    document.body.classList.add('onetrust-alert-box-open');
  }

  OneTrust.OnConsentChanged(() => {
    if (OneTrust.IsAlertBoxClosed()) {
      document.body.classList.remove('onetrust-alert-box-open');
    }
  });
}

